(function() {
  const STORAGE_KEY = 'minimal-todo-items';
  let todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
  let currentFilter = 'all';

  const form = document.getElementById('todo-form');
  const input = document.getElementById('todo-input');
  const list = document.getElementById('todo-list');
  const emptyState = document.getElementById('empty-state');
  const footer = document.getElementById('todo-footer');
  const taskCount = document.getElementById('task-count');
  const clearBtn = document.getElementById('clear-completed');
  const filterBtns = document.querySelectorAll('.filter-btn');

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') return todos.filter(t => !t.completed);
    if (currentFilter === 'completed') return todos.filter(t => t.completed);
    return todos;
  }

  function priorityOrder(p) {
    if (p === 'high') return 0;
    if (p === 'medium') return 1;
    return 2;
  }

  function render() {
    const filtered = getFilteredTodos();
    // Sort: incomplete first, then by priority
    filtered.sort((a, b) => {
      if (a.completed !== b.completed) return a.completed ? 1 : -1;
      return priorityOrder(a.priority) - priorityOrder(b.priority);
    });

    list.innerHTML = '';

    filtered.forEach(todo => {
      const li = document.createElement('li');
      li.className = 'todo-item' + (todo.completed ? ' completed' : '');
      li.dataset.id = todo.id;

      li.innerHTML = `
        <div class="todo-checkbox" data-action="toggle">
          <svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"></polyline></svg>
        </div>
        <div class="todo-content">
          <div class="todo-text">${escapeHtml(todo.text)}</div>
          <span class="todo-priority ${todo.priority}">${todo.priority}</span>
        </div>
        <button class="btn-delete" data-action="delete" aria-label="Delete task">
          <svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
        </button>
      `;

      list.appendChild(li);
    });

    // Empty state
    if (filtered.length === 0) {
      emptyState.classList.add('visible');
    } else {
      emptyState.classList.remove('visible');
    }

    // Footer
    if (todos.length === 0) {
      footer.classList.add('hidden');
    } else {
      footer.classList.remove('hidden');
      const active = todos.filter(t => !t.completed).length;
      taskCount.textContent = `${active} task${active !== 1 ? 's' : ''} remaining`;
    }
  }

  function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Add todo
  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const text = input.value.trim();
    if (!text) return;

    const priorityEl = document.querySelector('input[name="priority"]:checked');
    const priority = priorityEl ? priorityEl.value : 'medium';

    todos.push({
      id: generateId(),
      text: text,
      priority: priority,
      completed: false,
      createdAt: Date.now()
    });

    input.value = '';
    save();
    render();
    input.focus();
  });

  // Toggle & Delete via delegation
  list.addEventListener('click', function(e) {
    const target = e.target.closest('[data-action]');
    if (!target) return;

    const li = target.closest('.todo-item');
    const id = li.dataset.id;
    const action = target.dataset.action;

    if (action === 'toggle') {
      const todo = todos.find(t => t.id === id);
      if (todo) todo.completed = !todo.completed;
    } else if (action === 'delete') {
      todos = todos.filter(t => t.id !== id);
    }

    save();
    render();
  });

  // Filters
  filterBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;
      render();
    });
  });

  // Clear completed
  clearBtn.addEventListener('click', function() {
    todos = todos.filter(t => !t.completed);
    save();
    render();
  });

  // Initial render
  render();
})();

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
  background: #FAFAF8;
  color: #1a1a1a;
  line-height: 1.6;
  min-height: 100vh;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 80px 24px 48px;
}

header {
  margin-bottom: 48px;
}

h1 {
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1a1a1a;
  line-height: 1.1;
}

.subtitle {
  color: #6B7280;
  font-size: 1rem;
  margin-top: 8px;
}

/* Form */
.todo-form {
  margin-bottom: 32px;
}

#todo-input {
  width: 100%;
  padding: 16px 20px;
  font-size: 1rem;
  font-family: inherit;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  background: #fff;
  color: #1a1a1a;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

#todo-input:focus {
  border-color: #5B7B6A;
  box-shadow: 0 0 0 3px rgba(91, 123, 106, 0.1);
}

#todo-input::placeholder {
  color: #9CA3AF;
}

.form-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  gap: 16px;
}

.priority-selector {
  display: flex;
  gap: 8px;
}

.priority-option {
  cursor: pointer;
}

.priority-option input {
  display: none;
}

.priority-badge {
  display: inline-block;
  padding: 6px 14px;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: 20px;
  border: 1px solid transparent;
  transition: all 0.2s;
}

.priority-badge.low {
  background: #f0fdf4;
  color: #15803d;
  border-color: #bbf7d0;
}

.priority-badge.medium {
  background: #fefce8;
  color: #a16207;
  border-color: #fde68a;
}

.priority-badge.high {
  background: #fef2f2;
  color: #b91c1c;
  border-color: #fecaca;
}

.priority-option input:checked + .priority-badge.low {
  background: #15803d;
  color: #fff;
  border-color: #15803d;
}

.priority-option input:checked + .priority-badge.medium {
  background: #a16207;
  color: #fff;
  border-color: #a16207;
}

.priority-option input:checked + .priority-badge.high {
  background: #b91c1c;
  color: #fff;
  border-color: #b91c1c;
}

.btn-add {
  padding: 10px 24px;
  font-size: 0.875rem;
  font-weight: 600;
  font-family: inherit;
  background: #5B7B6A;
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s;
  white-space: nowrap;
}

.btn-add:hover {
  background: #4a6857;
}

/* Filters */
.filters {
  display: flex;
  gap: 4px;
  margin-bottom: 24px;
  border-bottom: 1px solid #E5E7EB;
  padding-bottom: 0;
}

.filter-btn {
  padding: 8px 16px;
  font-size: 0.875rem;
  font-family: inherit;
  font-weight: 500;
  color: #6B7280;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s;
  margin-bottom: -1px;
}

.filter-btn:hover {
  color: #1a1a1a;
}

.filter-btn.active {
  color: #5B7B6A;
  border-bottom-color: #5B7B6A;
}

/* Todo List */
.todo-list {
  list-style: none;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  margin-bottom: 8px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  transition: opacity 0.2s, transform 0.2s;
  animation: slideIn 0.2s ease;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.todo-item.completed {
  opacity: 0.55;
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
}

.todo-checkbox {
  width: 22px;
  height: 22px;
  border: 2px solid #D1D5DB;
  border-radius: 50%;
  cursor: pointer;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  background: #fff;
}

.todo-checkbox:hover {
  border-color: #5B7B6A;
}

.todo-item.completed .todo-checkbox {
  background: #5B7B6A;
  border-color: #5B7B6A;
}

.todo-checkbox svg {
  width: 12px;
  height: 12px;
  fill: none;
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  transition: opacity 0.2s;
}

.todo-item.completed .todo-checkbox svg {
  opacity: 1;
}

.todo-content {
  flex: 1;
  min-width: 0;
}

.todo-text {
  font-size: 0.9375rem;
  font-weight: 500;
  color: #1a1a1a;
  word-break: break-word;
}

.todo-priority {
  display: inline-block;
  padding: 2px 10px;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: 12px;
  margin-top: 4px;
}

.todo-priority.low {
  background: #f0fdf4;
  color: #15803d;
}

.todo-priority.medium {
  background: #fefce8;
  color: #a16207;
}

.todo-priority.high {
  background: #fef2f2;
  color: #b91c1c;
}

.btn-delete {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  color: #9CA3AF;
  transition: all 0.2s;
  flex-shrink: 0;
}

.btn-delete:hover {
  background: #fef2f2;
  color: #b91c1c;
}

.btn-delete svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: #9CA3AF;
  font-size: 0.9375rem;
  display: none;
}

.empty-state.visible {
  display: block;
}

/* Footer */
.todo-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  margin-top: 16px;
  border-top: 1px solid #E5E7EB;
  font-size: 0.875rem;
  color: #6B7280;
}

.todo-footer.hidden {
  display: none;
}

.btn-clear {
  padding: 6px 16px;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  color: #6B7280;
  background: none;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-clear:hover {
  background: #fef2f2;
  color: #b91c1c;
  border-color: #fecaca;
}

/* Responsive */
@media (max-width: 480px) {
  .container {
    padding: 48px 16px 32px;
  }

  h1 {
    font-size: 2.25rem;
  }

  .form-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .priority-selector {
    justify-content: center;
  }

  .btn-add {
    width: 100%;
    text-align: center;
  }
}
